patch:
diff --git a/repro-19033.js b/repro-19033.js
new file mode 100644
index 0000000..f26f086
--- /dev/null
+++ b/repro-19033.js
@@ -0,0 +1,78 @@
+"use strict";
+/* eslint-disable no-console, no-tabs, @eslint-community/eslint-comments/disable-enable-pair -- standalone repro script */
+
+/*
+ * Reproduction for eslint/eslint#19033: no-lonely-if autofix lifts the inner `if`
+ * out of its `else { ... }` block, so a following outer `else` re-binds to it.
+ *
+ *   node repro-19033.js                         # this checkout (./lib/api)
+ *   ESLINT_PATH=<dir of an eslint package> node repro-19033.js
+ *
+ * Exits 1 if any case's autofix changes runtime behavior.
+ */
+
+const { Linter } = require(process.env.ESLINT_PATH || "./lib/api");
+
+const cases = [
+
+    // exact snippet from the report
+    `if (true)
+	if (false) {}
+	else { if (false) {} }
+else throw Error('This \`else\` should have been unreachable!');`,
+
+    // variants of the same dangling-else shape
+    "if (true) if (false) {} else { if (false) {} else if (false) {} } else throw Error('x');",
+    "if (true) l: if (false) {} else { if (false) {} } else throw Error('x');",
+    "if (true) if (false) {} else { if (false) {} } /*c*/ else throw Error('x');",
+    "if (true) if (false) {} else if (false) {} else { if (false) {} } else throw Error('x');",
+    "if (true) if (false) {} else { if (false) ; } else throw Error('x');"
+];
+
+const linter = new Linter({ configType: "flat" });
+const config = { rules: { "no-lonely-if": "error" } };
+
+/**
+ * Runs the snippet and reports whether it threw.
+ * @param {string} src Source to run.
+ * @returns {string} "ok" or "threw: <message>".
+ */
+function run(src) {
+    try {
+        new Function(src)(); // eslint-disable-line no-new-func -- repro only
+        return "ok";
+    } catch (err) {
+        return `threw: ${err.message}`;
+    }
+}
+
+console.log(`eslint ${linter.version} from ${process.env.ESLINT_PATH || "./lib/api"}\n`);
+
+let unsafe = 0;
+
+for (const code of cases) {
+    const reports = linter.verify(code, config);
+    const { output } = linter.verifyAndFix(code, config);
+    const before = run(code);
+    const after = run(output);
+    const changed = before !== after;
+
+    if (changed) {
+        unsafe++;
+    }
+
+    console.log(`[${changed ? "UNSAFE FIX" : "ok"}] reports=${reports.length}`);
+    for (const m of reports) {
+        console.log(`  ${m.line}:${m.column} ${m.message}`);
+    }
+    console.log(`  input:  ${code.replace(/\n\s*/gu, " ")}`);
+    console.log(`  output: ${output.replace(/\n\s*/gu, " ")}`);
+    console.log(`  runtime: original ${before} | fixed ${after}\n`);
+}
+
+if (unsafe) {
+    console.log(`BUG REPRODUCED: ${unsafe}/${cases.length} autofixes changed semantics (outer \`else\` re-bound to the lifted inner \`if\`).`);
+    process.exitCode = 1;
+} else {
+    console.log("Not reproduced: no case was reported/fixed unsafely.");
+}
